#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> a(N);
    for (int i = 0; i < N; i++) cin >> a[i];

    if (N == 1) {
        cout << a[0] << " 0\n";
        return 0;
    }

    // Prefix sums for quick range sum
    vector<long long> pref(N+1, 0);
    for (int i = 0; i < N; i++) pref[i+1] = pref[i] + a[i];

    auto rangeSum = [&](int l, int r) {
        if (l > r) return 0LL;
        return pref[r+1] - pref[l];
    };

    // dp[l][r] = max net advantage for player to move on interval [l, r]
    vector<vector<long long>> dp(N, vector<long long>(N, 0));

    for (int len = 1; len <= N; len++) {
        for (int l = 0; l + len - 1 < N; l++) {
            int r = l + len - 1;
            if (len == 1) {
                dp[l][r] = a[l];
            } else {
                dp[l][r] = max(
                    a[l] + rangeSum(l+1, r) - dp[l+1][r],
                    a[r] + rangeSum(l, r-1) - dp[l][r-1]
                );
            }
        }
    }

    long long total = rangeSum(0, N-1);
    long long first = dp[0][N-1];
    long long second = total - first;

    cout << first << " " << second << "\n";

    return 0;
}

