#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int64> a(N);
    for (int i = 0; i < N; ++i) cin >> a[i];

    // dp[l][r][t]:
    // interval [l..r] is already occupied/available game segment,
    // and all chosen boxes form one contiguous block.
    // It is the current player's turn.
    // t=0: current player is the one who started the game on this segment
    // t=1: current player is the other player
    //
    // We store value = (score of starter) - (score of other player)
    // from optimal play on remaining boxes outside [l..r], assuming [l..r]
    // are already taken and future moves can only extend to l-1 or r+1.
    //
    // Base: if [0..N-1], no moves remain => 0.
    //
    // Transition:
    // If t=0 (starter's turn), picking x adds +a[x] to difference.
    // If t=1, picking x adds -a[x].
    //
    // Since after first move the occupied set is always contiguous,
    // the whole game can be viewed as:
    // choose first box i, then alternately extend left/right.
    //
    // For each possible first move i, total diff =
    // a[i] + dp[i][i][1]
    // because after starter takes i, it's other player's turn.

    static int64 dp[2005][2005][2];

    for (int len = N; len >= 1; --len) {
        for (int l = 0; l + len - 1 < N; ++l) {
            int r = l + len - 1;
            if (l == 0 && r == N - 1) {
                dp[l][r][0] = dp[l][r][1] = 0;
                continue;
            }

            // starter's turn
            int64 best0 = LLONG_MIN;
            if (l > 0) best0 = max(best0, a[l - 1] + dp[l - 1][r][1]);
            if (r + 1 < N) best0 = max(best0, a[r + 1] + dp[l][r + 1][1]);
            dp[l][r][0] = best0;

            // other player's turn
            int64 best1 = LLONG_MAX;
            if (l > 0) best1 = min(best1, -a[l - 1] + dp[l - 1][r][0]);
            if (r + 1 < N) best1 = min(best1, -a[r + 1] + dp[l][r + 1][0]);
            dp[l][r][1] = best1;
        }
    }

    int64 total = 0;
    for (auto x : a) total += x;

    int64 bestDiff = LLONG_MIN;
    for (int i = 0; i < N; ++i) {
        bestDiff = max(bestDiff, a[i] + dp[i][i][1]);
    }

    int64 sugim = (total + bestDiff) / 2;
    int64 sigma = total - sugim;

    cout << sugim << " " << sigma << '\n';
    return 0;
}

