#define MAX_N 3000

int a[MAX_N];
long long dp[MAX_N][MAX_N];
int n;

long long max(long long x, long long y) {
    return x > y ? x : y;
}

int main() {
    scanf("%d", &n);
    long long total = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
        total += a[i];
    }

    // dp[l][r] = maximum total the current player can obtain from subarray a[l..r]
    // when it's their turn and the segment is contiguous.
    for (int len = 1; len <= n; len++) {
        for (int l = 0; l + len - 1 < n; l++) {
            int r = l + len - 1;
            if (len == 1) {
                dp[l][r] = a[l];
            } else {
                dp[l][r] = max(a[l] - dp[l+1][r], a[r] - dp[l][r-1]);
            }
        }
    }

    // The first player can start at any position, so the optimal first move
    // gives the first player the maximum possible advantage.
    long long best = 0;
    for (int i = 0; i < n; i++) {
        long long score;
        if (i == 0) {
            score = a[i] - dp[i+1][n-1];
        } else if (i == n-1) {
            score = a[i] - dp[0][i-1];
        } else {
            // Pick i, then opponent can choose from left segment or right segment.
            // Actually after picking i, the remaining is two separate segments.
            // But opponent will pick the best adjacent: either left or right of i.
            // We must simulate: if first picks i, game continues on both sides.
            // The opponent can choose the better side for them.
            // We can think: first gets a[i] + min(remaining after opponent's optimal).
            // Remaining after picking i: left part [0..i-1] and right part [i+1..n-1].
            // Opponent will pick from one end of the whole. So opponent's best is
            // max(dp[0][i-1], dp[i+1][n-1]).
            // Then first's total = a[i] + (total - a[i] - opponent_best) = total - opponent_best.
            // Actually we need difference: first - second = a[i] - max(dp[0][i-1], dp[i+1][n-1]).
            long long opp = dp[0][i-1] > dp[i+1][n-1] ? dp[0][i-1] : dp[i+1][n-1];
            score = a[i] - opp;
        }
        if (score > best) best = score;
    }

    long long first = (total + best) / 2;
    long long second = total - first;
    printf("%lld %lld\n", first, second);

    return 0;
}

