int main() {
    int n;
    scanf("%d", &n);

    long long *a = malloc(n * sizeof(long long));
    for (int i = 0; i < n; i++) {
        scanf("%lld", &a[i]);
    }

    int sugim_len = (n + 1) / 2;

    // Compute prefix sums
    long long *prefix = malloc((n + 1) * sizeof(long long));
    prefix[0] = 0;
    for (int i = 0; i < n; i++) {
        prefix[i+1] = prefix[i] + a[i];
    }

    long long total = prefix[n];
    long long max_sugim = -1e18;

    for (int i = 0; i + sugim_len <= n; i++) {
        long long s = prefix[i + sugim_len] - prefix[i];
        if (s > max_sugim) max_sugim = s;
    }

    long long sigma = total - max_sugim;

    printf("%lld %lld\n", max_sugim, sigma);

    free(a);
    free(prefix);
    return 0;
}

