typedef long long ll;

static int cmp_ll_desc(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return 1;
    if (x > y) return -1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *a = (ll *)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &a[i]);

    if (N == 1) {
        printf("%lld 0\n", a[0]);
        free(a);
        return 0;
    }

    /* 
       After the first move, all future moves must stay adjacent to already chosen boxes,
       so the chosen boxes always form one contiguous segment.
       Thus the game is equivalent to:
       - choose a starting box
       - repeatedly take left end or right end of the current remaining interval

       For optimal play, the final set of turns by parity is fixed:
       one player gets ceil(N/2) boxes, the other gets floor(N/2) boxes.
       The first player can always force taking the larger values among one parity
       of positions in some ordering, and overall the result becomes:
       sort descending, players alternately take.
    */

    qsort(a, N, sizeof(ll), cmp_ll_desc);

    ll sugim = 0, sigma = 0;
    for (int i = 0; i < N; i++) {
        if (i % 2 == 0) sugim += a[i];
        else sigma += a[i];
    }

    printf("%lld %lld\n", sugim, sigma);

    free(a);
    return 0;
}

