public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[] a = new int[N];
        for (int i = 0; i < N; i++) {
            a[i] = sc.nextInt();
        }

        long sumEven = 0, sumOdd = 0;
        for (int i = 0; i < N; i++) {
            if (i % 2 == 0) sumEven += a[i];
            else sumOdd += a[i];
        }

        long first, second;
        if (N % 2 == 0) {
            // Even length: first can take all even indices or all odd indices
            if (sumEven >= sumOdd) {
                first = sumEven;
                second = sumOdd;
            } else {
                first = sumOdd;
                second = sumEven;
            }
        } else {
            // Odd length: first can take the middle and then mirror
            long total = sumEven + sumOdd;
            long middle = a[N / 2];
            long sideSumEven = sumEven - middle; // even indices excluding middle
            long sideSumOdd = sumOdd;            // odd indices

            // First can force max(sideSumEven, sideSumOdd) + middle
            first = middle + Math.max(sideSumEven, sideSumOdd);
            second = total - first;
        }

        System.out.println(first + " " + second);
        sc.close();
    }
}

