import java.io.*;
import java.util.*;

/*
We have N boxes in a row with values a[i].
Players alternately choose an empty box:
- On the first move, any box may be chosen.
- Thereafter, the chosen box must be adjacent to at least one already chosen box.

Thus, after the first move, the set of chosen boxes is always a contiguous interval,
and each move extends the interval by taking either the left neighbor or the right neighbor.

If the first chosen position is s, then the remaining game is:
starting from interval [s, s], players alternately take from left end or right end
until all boxes are taken.

Let f(l, r) be the maximum score difference (current player score - other player score)
obtainable from the state where the already chosen interval is [l, r], so remaining boxes
are [0..l-1] and [r+1..N-1], and current player moves next.

Transition:
f(l, r) = max(
    a[l-1] - f(l-1, r)   if l > 0,
    a[r+1] - f(l, r+1)   if r+1 < N
)

Base: f(0, N-1) = 0.

For a fixed first move s:
first player immediately gains a[s], then second player faces state f(s, s).
So final difference = a[s] - f(s, s).

First player chooses s maximizing this.
If total sum is S and final difference is D, then:
first = (S + D) / 2
second = S - first

We compute f by interval length descending / remaining count ascending.
Complexity: O(N^2), memory O(N^2), acceptable for moderate N.
*/

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        long[] a = new long[N];
        long sum = 0;
        for (int i = 0; i < N; i++) {
            a[i] = fs.nextLong();
            sum += a[i];
        }

        if (N == 1) {
            System.out.println(a[0] + " 0");
            return;
        }

        long[][] dp = new long[N][N];

        // dp[l][r] for increasing interval length
        // base dp[0][N-1] = 0 already
        for (int len = N - 1; len >= 1; len--) {
            for (int l = 0; l + len - 1 < N; l++) {
                int r = l + len - 1;
                long best = Long.MIN_VALUE;

                if (l > 0) {
                    best = Math.max(best, a[l - 1] - dp[l - 1][r]);
                }
                if (r + 1 < N) {
                    best = Math.max(best, a[r + 1] - dp[l][r + 1]);
                }
                dp[l][r] = best;
            }
        }

        long bestDiff = Long.MIN_VALUE;
        for (int s = 0; s < N; s++) {
            long diff = a[s] - dp[s][s];
            if (diff > bestDiff) bestDiff = diff;
        }

        long sugim = (sum + bestDiff) / 2;
        long sigma = sum - sugim;
        System.out.println(sugim + " " + sigma);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
